  JComponent content(){JPanel shell=new JPanel(new BorderLayout());shell.setBackground(BG);JPanel side=new JPanel();side.setBackground(new Color(14,21,32));side.setPreferredSize(new Dimension(190,10));side.setLayout(new BoxLayout(side,BoxLayout.Y_AXIS));side.setBorder(new MatteBorder(0,0,0,1,new Color(45,56,72)));JLabel menu=new JLabel("  SECURITY CONSOLE");menu.setForeground(MUTED);menu.setBorder(new EmptyBorder(22,8,15,0));side.add(menu);JTabbedPane tabs=new JTabbedPane();tabs.setUI(new BasicTabbedPaneUI(){@Override protected int calculateTabAreaHeight(int placement,int runs,int maxTabHeight){return 0;}@Override protected int calculateTabAreaWidth(int placement,int runs,int maxTabWidth){return 0;}});tabs.setBackground(BG);tabs.setForeground(Color.WHITE);tabs.addTab("Dashboard",dashboard());tabs.addTab("IP Scanner",scanner());tabs.addTab("Port Analysis",analysis());tabs.addTab("Firewall",firewallPage());tabs.addTab("Device Health",healthPage());tabs.addTab("Audit Logs",auditPage());tabs.addTab("Live Endpoints",endpointPage());String[] labels={"▦  Dashboard","⌕  IP Scanner","◉  Port Analysis","⬡  Firewall","▣  Device Health","☷  Audit Logs","◈  Live Endpoints"};for(int i=0;i<labels.length;i++){final int n=i;JButton b=new JButton(labels[i]);b.setHorizontalAlignment(SwingConstants.LEFT);b.setForeground(i==0?GOLD:MUTED);b.setBackground(new Color(14,21,32));b.setBorder(new EmptyBorder(12,14,12,4));b.setFocusPainted(false);b.addActionListener(e->tabs.setSelectedIndex(n));side.add(b);}side.add(Box.createVerticalGlue());shell.add(side,BorderLayout.WEST);shell.add(tabs,BorderLayout.CENTER);return shell;}
