  JLabel mirror(JLabel source){JLabel copy=new JLabel(source.getText());source.addPropertyChangeListener("text",e->copy.setText(String.valueOf(e.getNewValue())));return copy;}
  JPanel portChart=new JPanel(){
    protected void paintComponent(Graphics gg){super.paintComponent(gg);Graphics2D g=(Graphics2D)gg.create();
      g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);
      int[] values={opens,closes,filters};String[] labels={"OPEN","CLOSED","FILTERED"};Color[] colors={GOLD,GREEN,new Color(119,149,188)};
      int max=Math.max(1,Math.max(values[0],Math.max(values[1],values[2])));int w=getWidth(),h=getHeight();
      int chartTop=20,chartBottom=h-38;int barW=Math.max(20,Math.min(65,w/9));
      for(int i=0;i<3;i++){int x=(i+1)*w/4-barW/2;int height=(int)((chartBottom-chartTop)*(values[i]/(double)max));
        g.setColor(new Color(48,61,78));g.fillRoundRect(x,chartTop,barW,chartBottom-chartTop,8,8);
        g.setColor(colors[i]);g.fillRoundRect(x,chartBottom-height,barW,Math.max(2,height),8,8);
        g.setColor(new Color(224,230,239));g.drawString(""+values[i],x+barW/3,Math.max(12,chartBottom-height-5));
        g.setColor(MUTED);g.drawString(labels[i],x-5,h-12);
      }g.dispose();
    }
  };

  JPanel dashboard(){JPanel p=page();heading(p,"Security Dashboard","Network visibility, endpoint posture and Zero Trust policy status.");JPanel m=new JPanel(new GridLayout(1,4,10,10));m.setOpaque(false);m.add(metric("NMAP ENGINE",nmap,"Local scan engine"));m.add(metric("OPEN PORTS",open,"Services accepting connections"));m.add(metric("FILTERED",filtered,"No response / possible filtering"));m.add(metric("DEVICE POSTURE",posture,"Local endpoint baseline"));p.add(m);p.add(Box.createVerticalStrut(13));JPanel row=new JPanel(new GridLayout(1,2,10,10));row.setOpaque(false);JPanel c=card("NETWORK PORT OVERVIEW");JPanel counts=new JPanel(new GridLayout(1,3,8,8));counts.setOpaque(false);counts.add(metric("OPEN",mirror(open),"Exposure"));counts.add(metric("CLOSED",mirror(closed),"RST / ICMP response"));counts.add(metric("FILTERED",mirror(filtered),"No response"));c.add(counts,BorderLayout.CENTER);JPanel a=card("ACTIVE SECURITY FINDINGS");a.add(new JScrollPane(alerts),BorderLayout.CENTER);row.add(c);row.add(a);p.add(row);p.add(Box.createVerticalStrut(12));JPanel chartCard=card("LIVE SCAN PORT DISTRIBUTION • ACTUAL NMAP RESULTS");portChart.setBackground(new Color(18,27,42));portChart.setPreferredSize(new Dimension(500,150));chartCard.add(portChart,BorderLayout.CENTER);p.add(chartCard);p.add(Box.createVerticalStrut(12));JPanel d=card("DEVICE / SCAN CONTEXT");d.add(device,BorderLayout.CENTER);JButton scan=goldButton("START NEW SCAN");scan.addActionListener(e->{JTabbedPane t=findTabs(this);if(t!=null)t.setSelectedIndex(1);});d.add(scan,BorderLayout.EAST);p.add(d);p.add(Box.createVerticalGlue());return p;}
  JPanel scanner(){JPanel p=page();heading(p,"Network IP Scanner","Nmap TCP scan with service identification, exposure rating and recommended action.");JPanel f=card("SCAN CONFIGURATION");JPanel g=new JPanel(new GridLayout(3,2,8,8));g.setOpaque(false);g.add(label("Target IPv4"));g.add(target);g.add(label("Scan profile"));g.add(profile);g.add(label("Custom ports"));g.add(customPorts);f.add(g,BorderLayout.CENTER);f.add(authorized,BorderLayout.SOUTH);JButton run=goldButton("RUN AUTHORIZED SCAN");run.addActionListener(e->runScan());f.add(run,BorderLayout.EAST);p.add(f);p.add(Box.createVerticalStrut(10));JTable table=new JTable(model);table.setRowHeight(26);table.setFillsViewportHeight(true);table.setAutoCreateRowSorter(true);JPanel t=card("SCAN RESULTS • SELECT A ROW FOR PORT EXPLANATION");t.add(new JScrollPane(table),BorderLayout.CENTER);table.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&table.getSelectedRow()>=0){int r=table.convertRowIndexToModel(table.getSelectedRow());explain(String.valueOf(model.getValueAt(r,0)),String.valueOf(model.getValueAt(r,2)),String.valueOf(model.getValueAt(r,1)));}});p.add(t);p.add(Box.createVerticalStrut(8));p.add(scroll("PORT DETAILS / SCAN OUTPUT",scanText));return p;}
  JPanel analysis(){JPanel p=page();heading(p,"Port Risk Analysis","Open ports are exposed services, not proof of malware or compromise.");p.add(scroll("SELECT A PORT IN THE SCANNER TO VIEW ITS RISK AND MITIGATION",scanText));p.add(scroll("ACTIVE FINDINGS",alerts));return p;}
  JPanel firewallPage(){JPanel p=page();heading(p,"Firewall & Packet Response Analysis","Nmap state interpretation plus internal local firewall configuration check.");JPanel c=card("PACKET RESPONSE BEHAVIOUR");JTextArea guide=area();guide.setText("FILTERED (DROPPED): Probe receives no response / times out. Consistent with a firewall or packet filter silently dropping unsolicited traffic. PASS for that probe only; timeout can also be caused by routing, packet loss or a down host.\n\nCLOSED (RST / ICMP UNREACHABLE): Host responds immediately, commonly with TCP RST or ICMP unreachable. No application is listening on that port. This does NOT conclusively prove that no firewall exists; a firewall may actively reject packets.\n\nOPEN: A service accepted the TCP connection. Treat as exposed attack surface. Identify owner, patch it, restrict source addresses or disable it if unnecessary.");c.add(new JScrollPane(guide),BorderLayout.CENTER);p.add(c);p.add(Box.createVerticalStrut(10));JButton check=goldButton("CHECK LOCAL HOST FIREWALL");check.addActionListener(e->checkLocal(true));p.add(check);p.add(scroll("LOCAL FIREWALL CHECK RESULTS",firewallText));return p;}
  JPanel healthPage(){JPanel p=page();heading(p,"Device Health & Posture Assessment","Local endpoint checks only. Remote endpoint health requires an authenticated agent or approved SSH / WinRM.");JButton b=goldButton("RUN LOCAL DEVICE CHECK");b.addActionListener(e->checkLocal(true));p.add(b);p.add(scroll("LOCAL DEVICE ASSESSMENT",healthText));JTextArea req=area();req.setText("REMOTE DEVICE CHECKS REQUIRE AN AUTHENTICATED ENDPOINT AGENT:\n• OS patch / kernel version and last security update timestamp.\n• Antivirus / EDR service state and signature-definition freshness.\n• BitLocker (Windows), LUKS (Linux) or FileVault (macOS) encryption state.\n• Suspicious processes, unauthorized administrators, risky services and listeners on 0.0.0.0.\n• IP reputation via AbuseIPDB or another threat-intelligence feed (API key required), plus authorized subnet / VLAN inventory.\n\nStatus remains NOT VERIFIED until an authenticated agent or administrator-approved remote query returns signed/validated results. A port scan cannot establish these endpoint properties.");p.add(scroll("REMOTE DEVICE VERIFICATION REQUIREMENTS",req));return p;}
  JPanel auditPage(){JPanel p=page();heading(p,"Audit Logs","Local hostname, device IP, current user, target IP, timestamp and action history.");JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.setOpaque(false);JButton r=goldButton("REFRESH LOGS"),x=new JButton("EXPORT CSV");r.addActionListener(e->refreshAudit());x.addActionListener(e->exportAudit());actions.add(r);actions.add(x);p.add(actions);p.add(scroll("AUDIT EVENT HISTORY",auditText));return p;}
  JLabel label(String s){JLabel l=new JLabel(s);l.setForeground(MUTED);return l;}
  static JTextArea area(){JTextArea a=new JTextArea();a.setEditable(false);a.setLineWrap(true);a.setWrapStyleWord(true);a.setBackground(new Color(14,21,32));a.setForeground(new Color(213,222,235));a.setCaretColor(GOLD);a.setFont(new Font(Font.MONOSPACED,Font.PLAIN,12));a.setBorder(new EmptyBorder(8,8,8,8));return a;}
  void checkNmap(){boolean ok=commandOk("nmap","--version");nmap.setText(ok?"READY":"NOT INSTALLED");nmap.setForeground(ok?GREEN:RED);}
  boolean commandOk(String... c){try{Process p=new ProcessBuilder(c).redirectErrorStream(true).start();return p.waitFor(5,TimeUnit.SECONDS)&&p.exitValue()==0;}catch(Exception e){return false;}}
  void runScan(){String ip=target.getText().trim();if(!authorized.isSelected()){JOptionPane.showMessageDialog(this,"Confirm ownership or explicit permission before scanning.");log("SCAN_BLOCKED",ip,"Authorization not confirmed");return;}if(!validIp(ip)){JOptionPane.showMessageDialog(this,"Enter one valid IPv4 address. CIDR and hostnames are not accepted.");return;}if(!commandOk("nmap","--version")){JOptionPane.showMessageDialog(this,"Install Nmap and add it to PATH.");return;}List<String> cmd=new ArrayList<>(Arrays.asList("nmap","-sT","-sV","-T3","--reason"));String s=String.valueOf(profile.getSelectedItem());if(s.equals("Common web ports"))cmd.addAll(Arrays.asList("-p","21,22,23,25,53,80,110,139,143,443,445,3306,3389,5432,5900,8080,8443"));else if(s.equals("Custom port range")){String cp=customPorts.getText().trim();if(!cp.matches("\\d{1,5}(-\\d{1,5})?(,\\d{1,5}(-\\d{1,5})?)*")){JOptionPane.showMessageDialog(this,"Enter ports like 22,80,443 or 1-1000.");return;}cmd.addAll(Arrays.asList("-p",cp));}else cmd.addAll(Arrays.asList("--top-ports",s.equals("Top 1000 TCP")?"1000":"100"));cmd.add(ip);model.setRowCount(0);opens=closes=filters=0;updateCounts();scanText.setText("Running: "+String.join(" ",cmd));log("SCAN_STARTED",ip,String.join(" ",cmd));new SwingWorker<String,Void>(){protected String doInBackground()throws Exception{Process p=new ProcessBuilder(cmd).redirectErrorStream(true).start();String out=read(p.getInputStream());if(!p.waitFor(180,TimeUnit.SECONDS)){p.destroyForcibly();throw new IOException("Scan timed out");}if(p.exitValue()!=0)throw new IOException(out);return out;}protected void done(){try{String out=get();scanText.setText(out);parse(out);log("SCAN_COMPLETED",ip,"open="+opens+", closed="+closes+", filtered="+filters);}catch(Exception e){scanText.setText("Scan failed: "+e);log("SCAN_FAILED",ip,e.toString());}refreshAudit();}}.execute();}
  void parse(String out){model.setRowCount(0);for(String line:out.split("\\R")){String s=line.trim();if(s.matches("\\d+/tcp\\s+.*")){String[] a=s.split("\\s+",4);String port=a[0],state=a.length>1?a[1]:"?",service=a.length>2?a[2]:"unknown",version=a.length>3?a[3]:"";model.addRow(new Object[]{port,state,service,version,portRisk(service,port),action(service,port)});if(state.equals("open"))opens++;else if(state.equals("closed"))closes++;else if(state.contains("filtered"))filters++;}}updateCounts();alerts.setText("Open services: "+opens+". Review service ownership, version, credentials and network exposure. An open port is not proof of malware.\nClosed: "+closes+" (host responded, no listener).\nFiltered: "+filters+" (no definitive response; likely filtering but not conclusive).\n");risk.setText(opens>0?"RISK: REVIEW OPEN SERVICES":"RISK: NO OPEN PORTS REPORTED");}
  void updateCounts(){open.setText(""+opens);closed.setText(""+closes);filtered.setText(""+filters);portChart.repaint();}
  String portRisk(String s,String p){s=s.toLowerCase();if(p.equals("23")||p.equals("21")||p.equals("445")||p.equals("3389")||p.equals("5900")||p.equals("3306")||p.equals("5432")||s.contains("telnet")||s.contains("smb")||s.contains("rdp"))return "HIGH";if(p.equals("22")||p.equals("80")||p.equals("8080")||s.contains("ssh")||s.contains("http"))return "MEDIUM";if(p.equals("443")||s.contains("https"))return "LOW-MEDIUM";return "REVIEW";}
  String action(String s,String p){s=s.toLowerCase();if(p.equals("23")||s.contains("telnet"))return "Disable; use SSH";if(p.equals("21")||s.contains("ftp"))return "Prefer SFTP/FTPS";if(p.equals("445")||p.equals("139")||s.contains("smb"))return "Restrict SMB; patch";if(p.equals("3389")||s.contains("rdp"))return "VPN + MFA; allow-list";if(p.equals("5900")||s.contains("vnc"))return "Disable or VPN tunnel";if(p.equals("22")||s.contains("ssh"))return "Keys only; disable root";if(p.equals("3306")||p.equals("5432"))return "Private bind; allow-list";return "Patch and restrict sources";}
  String serviceDescription(String p,String s){String x=s.toLowerCase(Locale.ROOT);switch(p){case "21":return "FTP — File Transfer Protocol. Transfers files between a client and server; classic FTP does not encrypt credentials or file contents.";case "22":return "SSH — Secure Shell. Provides encrypted remote command-line access and secure file transfer (SCP/SFTP).";case "23":return "Telnet — remote terminal access without encryption; credentials and session data may be exposed on the network.";case "25":return "SMTP — mail transfer service used to relay email between mail servers.";case "53":return "DNS — resolves domain names to IP addresses; an exposed recursive resolver can be abused if misconfigured.";case "80":return "HTTP — serves websites and APIs without transport encryption.";case "443":return "HTTPS — serves websites and APIs over TLS encryption.";case "139":case "445":return "SMB — Windows file/printer sharing and network resource access.";case "3306":return "MySQL — database listener used by applications and administrators to query stored data.";case "3389":return "RDP — Microsoft Remote Desktop for interactive Windows administration.";case "5432":return "PostgreSQL — database listener for application and administrator connections.";case "5900":return "VNC — remote desktop screen/control service.";case "8080":return "HTTP alternate — commonly application servers, development consoles, proxies or web admin panels.";case "8443":return "HTTPS alternate — commonly secure application or administration interfaces.";default:return s.toUpperCase(Locale.ROOT)+" — service identified by Nmap. Confirm its exact role and owning application before deciding whether it should be exposed.";}}
String serviceConsequences(String p,String s){String x=s.toLowerCase(Locale.ROOT);if(p.equals("21")||p.equals("23")||x.contains("telnet")||x.contains("ftp"))return "If exposed to an untrusted network: credentials or transferred data may be intercepted; weak accounts may be guessed; an outdated daemon may contain exploitable flaws.";if(p.equals("445")||p.equals("139")||x.contains("smb"))return "If exposed broadly: attackers may probe file shares, exploit unpatched SMB vulnerabilities, steal data or use the host for lateral movement after another compromise.";if(p.equals("3389")||x.contains("rdp"))return "If exposed broadly: password spraying, credential theft and exploitation of unpatched remote-desktop components may lead to unauthorized interactive access.";if(p.equals("22")||x.contains("ssh"))return "If exposed broadly: automated login attempts and stolen/private-key misuse may lead to unauthorized shell access; outdated SSH components may also be vulnerable.";if(p.equals("3306")||p.equals("5432"))return "If reachable by untrusted clients: database contents may be exposed, altered or deleted if credentials, access rules or database software are weak.";if(p.equals("80")||p.equals("8080")||p.equals("443")||p.equals("8443")||x.contains("http"))return "If the hosted application is vulnerable or misconfigured: attackers may exploit web flaws, access admin panels or expose application data. TLS protects transport, not the application itself.";return "If the service has weak authentication, unsafe configuration or unpatched vulnerabilities, an attacker who can reach it may attempt unauthorized access or data exposure.";}
void explain(String p,String service,String state){StringBuilder b=new StringBuilder("PORT "+p+" • "+service.toUpperCase()+" • "+state.toUpperCase()+"\n\n");if(state.equals("open")){b.append("SERVICE NAME & FUNCTION\n").append(serviceDescription(p,service)).append("\n\nWHAT OPEN MEANS\nA process accepted a TCP connection. The service is reachable from the scanner's network position. Open does NOT mean malware is present and does NOT prove the device has been hacked.\n\nSECURITY CONSEQUENCES IF MISCONFIGURED\n").append(serviceConsequences(p,service)).append("\n\nRISK & RECOMMENDED ACTION\nRisk rating: ").append(portRisk(service,p)).append("\nAction: ").append(action(service,p)).append(". Confirm business need, patch the service, use strong authentication and restrict source IPs / VLANs. Disable the listener if it is not required.");}else if(state.equals("closed"))b.append("The host responded (commonly TCP RST or ICMP unreachable) but no application is listening. The probe reached the host. This does not prove that a firewall is absent because a firewall can actively reject packets.\n\nRecommended: verify that this port is intentionally unused and review host firewall policy.");else b.append("No definitive response was received. This is consistent with silent firewall dropping, but routing, packet loss or a down host can also cause a timeout. Validate using a known reachable host and compare with the local firewall configuration.\n\nRecommended: treat as filtered only with supporting evidence; do not claim this alone proves a firewall is enabled.");scanText.setText(b.toString());}
  void checkLocal(boolean logIt){new SwingWorker<String,Void>(){protected String doInBackground(){String os=System.getProperty("os.name","");if(os.toLowerCase().contains("win")){String q="Get-NetFirewallProfile | ForEach-Object { $_.Name + ':' + $_.Enabled + ':Inbound=' + $_.DefaultInboundAction }";return executeCommand(Arrays.asList("powershell.exe","-NoProfile","-Command",q));}if(os.toLowerCase().contains("linux"))return "UFW:\n"+executeCommand(Arrays.asList("sh","-c","command -v ufw >/dev/null && sudo -n ufw status verbose || echo 'UFW unavailable or needs admin'"))+"\nNFTABLES:\n"+executeCommand(Arrays.asList("sh","-c","command -v nft >/dev/null && sudo -n nft list ruleset || echo 'nft unavailable or needs admin'"));return "Unsupported OS firewall query: "+os;}protected void done(){try{String out=get();firewallText.setText(out);boolean win=out.contains("Domain:True")&&out.contains("Private:True")&&out.contains("Public:True")&&(out.contains("Inbound=Block")||out.contains("Inbound=2"));boolean lin=out.contains("Status: active")||out.contains("table inet")||out.contains("chain input");boolean pass=win||lin;firewall.setText(pass?"PASS / RULES FOUND":"REVIEW REQUIRED");firewall.setForeground(pass?GREEN:GOLD);posture.setText(pass?"BASELINE PASS":"REVIEW");posture.setForeground(pass?GREEN:GOLD);String ident="Hostname: "+hostname()+"\nCurrent OS user: "+System.getProperty("user.name")+"\nLocal IPv4: "+localIp()+"\nMAC: "+mac()+"\nOS: "+System.getProperty("os.name")+" "+System.getProperty("os.version")+"\nJava: "+System.getProperty("java.version");healthText.setText(ident+"\n\nFIREWALL CONFIGURATION\n"+out+"\n\nNOT VERIFIED HERE: EDR definition freshness, last security patch timestamp, disk encryption and process integrity. Those require elevated OS-specific checks or an authenticated endpoint agent.");device.setText(hostname()+" • "+localIp()+" • "+firewall.getText());if(logIt)log("LOCAL_POSTURE_CHECK",localIp(),posture.getText()+"; "+firewall.getText());}catch(Exception e){healthText.setText(e.toString());}}}.execute();}
  String hostname(){try{return InetAddress.getLocalHost().getHostName();}catch(Exception e){return "unknown";}}
  String localIp(){try{Enumeration<NetworkInterface> es=NetworkInterface.getNetworkInterfaces();while(es.hasMoreElements()){NetworkInterface n=es.nextElement();if(!n.isUp()||n.isLoopback())continue;Enumeration<InetAddress> as=n.getInetAddresses();while(as.hasMoreElements()){InetAddress a=as.nextElement();if(a instanceof Inet4Address&&!a.isLoopbackAddress())return a.getHostAddress();}}}catch(Exception ignored){}return "unavailable";}
  String mac(){try{byte[] m=NetworkInterface.getByInetAddress(InetAddress.getByName(localIp())).getHardwareAddress();StringJoiner j=new StringJoiner(":");for(byte b:m)j.add(String.format("%02X",b));return j.toString();}catch(Exception e){return "unavailable";}}
  void log(String action,String targetIp,String detail){try{Files.createDirectories(LOG.getParent());String line=LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME)+" | "+hostname()+" | "+localIp()+" | "+System.getProperty("user.name")+" | "+action+" | "+targetIp+" | "+detail.replace('\n',' ').replace('\r',' ')+'\n';Files.writeString(LOG,line,StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(IOException e){}refreshAudit();}
  void refreshAudit(){try{auditText.setText(Files.exists(LOG)?Files.readString(LOG):"No audit events recorded.");}catch(IOException e){auditText.setText(e.toString());}}
  void exportAudit(){JFileChooser c=new JFileChooser();c.setSelectedFile(new File("ztnss_audit.csv"));if(c.showSaveDialog(this)==JFileChooser.APPROVE_OPTION)try{StringBuilder b=new StringBuilder("timestamp,hostname,local_ip,user,action,target_ip,details\n");if(Files.exists(LOG))for(String l:Files.readAllLines(LOG)){String[] a=l.split(" \\| ",7);for(int i=0;i<a.length;i++){if(i>0)b.append(',');b.append('"').append(a[i].replace("\"","\"\"")).append('"');}b.append('\n');}Files.writeString(c.getSelectedFile().toPath(),b.toString());}catch(IOException e){JOptionPane.showMessageDialog(this,e.toString());}}
  static String executeCommand(List<String> c){try{Process p=new ProcessBuilder(c).redirectErrorStream(true).start();String o=read(p.getInputStream());p.waitFor(12,TimeUnit.SECONDS);return o;}catch(Exception e){return e.toString();}}
  static String read(InputStream in)throws IOException{try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){StringBuilder b=new StringBuilder();String s;while((s=r.readLine())!=null)b.append(s).append('\n');return b.toString();}}
  boolean validIp(String ip){String[] a=ip.split("\\.",-1);if(a.length!=4)return false;try{for(String x:a){if(x.isEmpty()||(x.length()>1&&x.startsWith("0")))return false;int n=Integer.parseInt(x);if(n<0||n>255)return false;}return true;}catch(Exception e){return false;}}
  static JTabbedPane findTabs(Container c){for(Component x:c.getComponents()){if(x instanceof JTabbedPane)return (JTabbedPane)x;if(x instanceof Container){JTabbedPane t=findTabs((Container)x);if(t!=null)return t;}}return null;}
