  // Authenticated live endpoint viewer: polls controller over HTTPS with normal Java certificate validation.
  JTextField controllerUrl=new JTextField("https://localhost:8443");
  JPasswordField viewerSecret=new JPasswordField();
  JTextArea endpointData=area();
  javax.swing.Timer endpointTimer;
  JPanel endpointPage(){
    JPanel p=page();heading(p,"Live Endpoint Trust Monitor","Real enrolled-device reports from the HTTPS controller; no simulated devices or scores.");
    JPanel form=card("CONTROLLER CONNECTION");
    JPanel fields=new JPanel(new GridLayout(2,2,10,10));fields.setOpaque(false);
    fields.add(label("HTTPS controller URL"));fields.add(controllerUrl);
    fields.add(label("Viewer authentication token"));fields.add(viewerSecret);
    form.add(fields,BorderLayout.CENTER);
    JPanel buttons=new JPanel(new FlowLayout(FlowLayout.LEFT,8,4));buttons.setOpaque(false);
    JButton refresh=goldButton("REFRESH LIVE DEVICES");
    JButton auto=goldButton("START AUTO REFRESH (15s)");
    refresh.addActionListener(e->refreshEndpoints());
    auto.addActionListener(e->{if(endpointTimer!=null&&endpointTimer.isRunning()){
      endpointTimer.stop();auto.setText("START AUTO REFRESH (15s)");
    }else{endpointTimer=new javax.swing.Timer(15000,e2->refreshEndpoints());endpointTimer.start();auto.setText("STOP AUTO REFRESH");refreshEndpoints();}});
    buttons.add(refresh);buttons.add(auto);form.add(buttons,BorderLayout.SOUTH);
    p.add(form);p.add(Box.createVerticalStrut(12));
    endpointData.setText("No live report loaded. Start the HTTPS controller, enroll an authorized endpoint, submit a report, and click REFRESH.\n\nUNKNOWN is not PASS. Reports contain raw endpoint evidence for review.");
    p.add(scroll("AUTHENTICATED DEVICE INVENTORY AND HEALTH EVIDENCE",endpointData));
    return p;
  }
  void refreshEndpoints(){
    String base=controllerUrl.getText().trim();
    if(!base.startsWith("https://")){endpointData.setText("BLOCKED: Controller URL must use HTTPS.");return;}
    String secret=new String(viewerSecret.getPassword());
    if(secret.isEmpty()){endpointData.setText("Enter the controller viewer token.");return;}
    endpointData.setText("Fetching authenticated endpoint reports...");
    new SwingWorker<String,Void>(){
      protected String doInBackground() throws Exception{
        java.net.http.HttpClient client=java.net.http.HttpClient.newBuilder()
          .connectTimeout(java.time.Duration.ofSeconds(7)).build();
        java.net.http.HttpRequest req=java.net.http.HttpRequest.newBuilder()
          .uri(java.net.URI.create(base.replaceAll("/+$","")+"/api/devices"))
          .header("Authorization","Bearer "+secret)
          .timeout(java.time.Duration.ofSeconds(15)).GET().build();
        java.net.http.HttpResponse<String> res=client.send(req,java.net.http.HttpResponse.BodyHandlers.ofString());
        return "HTTP "+res.statusCode()+"  |  LIVE CONTROLLER RESPONSE\n\n"+res.body();
      }
      protected void done(){try{endpointData.setText(get());}catch(Exception ex){endpointData.setText("Connection failed: "+ex.getMessage()+"\nCheck TLS certificate trust, URL, network, and controller availability.");}}
    }.execute();
  }

